import React, { useState, useEffect } from 'react';
import { useAuth } from '../context/AuthContext';
import { BookOpen, Code2, Server, Database, Rocket } from 'lucide-react';
import axios from 'axios';

const WeeklyFocus = () => {
    const { token } = useAuth();
    const [weeklyData, setWeeklyData] = useState([]);
    const [loading, setLoading] = useState(true);

    useEffect(() => {
        fetchWeeklyData();
    }, []);

    const fetchWeeklyData = async () => {
        try {
            const response = await axios.get(
                'http://localhost:8081/api/weekly',
                { headers: { Authorization: `Bearer ${token}` } }
            );
            setWeeklyData(response.data);
            setLoading(false);
        } catch (error) {
            console.error('Failed to fetch weekly data');
            setLoading(false);
        }
    };

    const weekColors = [
        'bg-blue-100 border-blue-400',
        'bg-purple-100 border-purple-400',
        'bg-green-100 border-green-400',
        'bg-orange-100 border-orange-400'
    ];

    if (loading) {
        return (
            <div className="flex items-center justify-center h-64">
                <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-blue-600"></div>
            </div>
        );
    }

    return (
        <div className="bg-white rounded-lg shadow-lg p-6">
            <h1 className="text-2xl font-bold mb-6 flex items-center gap-2">
                <Rocket className="text-purple-600" />
                Weekly Focus Areas - Month 4
            </h1>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                {weeklyData.map((week, index) => (
                    <div
                        key={week.week}
                        className={`border-l-4 rounded-lg p-5 shadow-sm ${weekColors[index % weekColors.length]}`}
                    >
                        <h2 className="text-xl font-bold mb-3">Week {week.week}</h2>
                        
                        <div className="space-y-3">
                            <div className="flex items-start gap-2">
                                <BookOpen size={18} className="text-blue-600 mt-1" />
                                <div>
                                    <span className="font-semibold">Java:</span>
                                    <span className="ml-2 text-gray-700">{week.java}</span>
                                </div>
                            </div>

                            <div className="flex items-start gap-2">
                                <Code2 size={18} className="text-green-600 mt-1" />
                                <div>
                                    <span className="font-semibold">LeetCode & DSA:</span>
                                    <span className="ml-2 text-gray-700">{week.leetcodeDsa}</span>
                                </div>
                            </div>

                            <div className="flex items-start gap-2">
                                <Server size={18} className="text-purple-600 mt-1" />
                                <div>
                                    <span className="font-semibold">Projects:</span>
                                    <span className="ml-2 text-gray-700">{week.projects}</span>
                                </div>
                            </div>

                            <div className="flex items-start gap-2">
                                <Database size={18} className="text-orange-600 mt-1" />
                                <div>
                                    <span className="font-semibold">Other:</span>
                                    <span className="ml-2 text-gray-700">{week.other}</span>
                                </div>
                            </div>
                        </div>
                    </div>
                ))}
            </div>
        </div>
    );
};

export default WeeklyFocus;
